function insRow5()
{
var description = new Array();
description[0] = "<tbody><tr><td><p>- En criterio del Editor, para la interpretaci&oacute;n de este art&iacute;culo, se debe tener en cuenta el art&iacute;culo <A href='ley_0549_1999.html#12A' >12A</A> de la Ley 549 de 1999, por el art&iacute;culo <A href='ley_2468_2025.html#12' >12</A> de la Ley 2468 de 2 de julio de 2025, 'por medio de la cual se modifica la Ley <A href='ley_0549_1999.html#0' >549</A> de 1999 con el fin de garantizar el financiamiento pasivo pensional de las entidades territoriales y el Fondo Nacional de Pensiones de las entidades territoriales'</p><p>(Por favor remitirse a la norma original para comprobar la vigencia del texto que se transcribe a continuaci&oacute;n:) </p><p><span class='i_aj'>'ART&Iacute;CULO <A href='ley_0549_1999.html#12A' >12A</A>. Las entidades territoriales que hayan cubierto el cien por ciento (100%) de su pasivo pensional en cada uno de los sectores del Fondo Nacional de Pensiones de las Entidades Territoriales (Fonpet), podr&aacute;n utilizar los recursos excedentes de cada sector, para la financiaci&oacute;n de proyectos de inversi&oacute;n social incluidos en su Plan de Desarrollo conforme la fuente de financiaci&oacute;n respectiva, siempre y cuando cumplan con los dem&aacute;s requisitos establecidos en la normativa vigente. Para tal efecto, se priorizar&aacute;n las fuentes propias de las entidades territoriales, seguidas de las dem&aacute;s fuentes, al momento de establecer los excedentes del sector prop&oacute;sito general. '</span></p> </td></tr></tbody>";
var z=document.getElementById('Table5').rows[0];
if (z==null) {
              var x=document.getElementById('Table5').insertRow(0)
              var y=x.insertCell(0)
              y.innerHTML=description
             }
else         {
              document.getElementById('Table5').deleteRow(0)
             }
}
