function insRow16()
{
var description = new Array();
description[0] = "<tbody><tr><td><p><span class='b_aj'>Texto original de la Ley 2294 de 2023:</span></p><p>ART&Iacute;CULO 340. Con el prop&oacute;sito de modernizar y fortalecer los servicios administrativos y t&eacute;cnicos de la C&aacute;mara de Representantes cr&eacute;anse las siguientes dependencias y cargos en la estructura y en la planta de personal de la Direcci&oacute;n Administrativa de la Corporaci&oacute;n: </p><p><A name='T&Iacute;TULO I'></A></p><p><span class='b_aj'></span>1. Subdirecci&oacute;n Administrativa: La Subdirecci&oacute;n Administrativa de la C&aacute;mara de Representantes tendr&aacute; a su cargo el desarrollo y ejecuci&oacute;n de pol&iacute;ticas, planes, proyectos, actividades, operaciones y procedimientos administrativos y presupuestales que sean asignadas y delegadas por el Director Administrativo, de conformidad con las normas legales, administrativas y t&eacute;cnicas vigentes y de los procedimientos establecidos para el efecto, as&iacute; mismo, reemplazar&aacute; al Director Administrativo en sus ausencias temporales. El Subdirector Administrativo, ser&aacute; funcionario del nivel directivo, grado 12, con la misma remuneraci&oacute;n salarial del Subsecretario General de la C&aacute;mara de Representantes y ser&aacute; de libre nombramiento y remoci&oacute;n. </p><p><A name='T&Iacute;TULO I'></A></p><p><span class='b_aj'></span>2. Oficina de Control Disciplinario Interno. La Oficina de Control Disciplinario Interno tendr&aacute; a su cargo el ejercicio de la potestad disciplinaria sobre los funcionarios y exfuncionarios p&uacute;blicos de la Corporaci&oacute;n; de acuerdo a las reglas establecidas en el C&oacute;digo &Uacute;nico Disciplinario o las normas que lo modifiquen y reemplacen; observando los tr&aacute;mites exigidos por la ley, los reglamentos y las disposiciones internas para dar cumplimiento al R&eacute;gimen Disciplinario. El Jefe de la Oficina de Control Disciplinario Interno ser&aacute; funcionario de nivel directivo, grado 13, de libre nombramiento y remoci&oacute;n. </p><p><A name='T&Iacute;TULO I'></A></p><p><span class='b_aj'></span>3. Divisi&oacute;n de Tecnolog&iacute;as de la Informaci&oacute;n y la Comunicaci&oacute;n (TIC). La Divisi&oacute;n de Tecnolog&iacute;as de la Informaci&oacute;n y la Comunicaci&oacute;n (TIC) de la Direcci&oacute;n Administrativa de la C&aacute;mara de Representantes tendr&aacute; a su cargo el desarrollo y ejecuci&oacute;n de las pol&iacute;ticas, planes, proyectos, actividades, operaciones y procedimientos administrativos y presupuestales propios de la Divisi&oacute;n, de conformidad con las normas legales, administrativas y t&eacute;cnicas vigentes y los procedimientos establecidos para el efecto. El Jefe de la Divisi&oacute;n de Tecnolog&iacute;as de la Informaci&oacute;n y la Comunicaci&oacute;n (TIC) ser&aacute; funcionario del nivel directivo, grado 10, de libre nombramiento y remoci&oacute;n. </p><p><A name='T&Iacute;TULO I'></A></p><p><span class='b_aj'></span>4. Divisi&oacute;n de Gesti&oacute;n Documental y Calidad. La Divisi&oacute;n de Gesti&oacute;n Documental y Calidad de la Direcci&oacute;n Administrativa de la C&aacute;mara de Representantes tendr&aacute; a su cargo el desarrollo y ejecuci&oacute;n de las pol&iacute;ticas, planes, proyectos, actividades, operaciones y procedimientos administrativos y presupuestales propios de la Divisi&oacute;n, de conformidad con las normas legales, administrativas y t&eacute;cnicas vigentes y los procedimientos establecidos para el efecto. El Jefe de la Divisi&oacute;n de Gesti&oacute;n Documental y Calidad ser&aacute; funcionario del nivel directivo, grado 10, de libre nombramiento y remoci&oacute;n. </p><p><A name='T&Iacute;TULO I'></A></p><p><span class='b_aj'></span>PAR&Aacute;GRAFO 1o. Dentro de los seis (6) meses siguientes a la entrada en vigencia de la presente ley, el Director Administrativo de la C&aacute;mara de Representantes expedir&aacute; los Actos Administrativos ajustando la planta de personal, creando o actualizando las denominaciones, funciones y requisitos de los cargos que se requieran para dar cumplimiento al presente art&iacute;culo. </p> </td></tr></tbody>";
var z=document.getElementById('Table16').rows[0];
if (z==null) {
              var x=document.getElementById('Table16').insertRow(0)
              var y=x.insertCell(0)
              y.innerHTML=description
             }
else         {
              document.getElementById('Table16').deleteRow(0)
             }
}
